/**
 * @distilled.cloud/proxmox: Proxmox VE API SDK for Effect.
 *
 * `./services` and `./property-strings.ts` are generated by
 * `scripts/generate.ts` from the structure of the API schema in Proxmox's
 * `pve-docs` package. Everything else in this folder is hand-written.
 *
 * One module per API area (`nodesLxc`, `nodesQemu`, `cluster`, ...).
 * Operation names combine the HTTP method and the path, because Proxmox
 * reuses operation names across paths. Most write operations start a task
 * and return its ID; {@link waitForTask} waits for it.
 *
 * @example
 * ```ts
 * import * as Proxmox from "@distilled.cloud/proxmox";
 *
 * const guests = yield* Proxmox.cluster.getClusterResources({ type: "vm" });
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export { ProxmoxProtocol, type ProxmoxOpError, type ProxmoxOpContext } from "./protocol.ts";
export {
  propertyString,
  PropertyStringError,
  type PropertyField,
  type PropertyFormat,
  type PropertyValue,
} from "./property-string.ts";
export { waitForTask, TaskFailed, TaskTimeout, type WaitForTaskOptions } from "./tasks.ts";
export * from "./services/index.ts";
